def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_rate = opp_c / n

    opp_last = history[-1][1]

    d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        d_streak += 1
        i -= 1

    c_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        c_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    rs = n - 10
    if rs < 0:
        rs = 0
    rec_len = n - rs
    rec_c = 0
    for j in range(rs, n):
        if history[j][1] == 'C':
            rec_c += 1
    rec_rate = rec_c / rec_len

    ts = n - 14
    if ts < 1:
        ts = 1
    aDD = 0
    aDC = 0
    aCD = 0
    aCC = 0
    for i in range(ts, n):
        prev = history[i - 1][0]
        curr = history[i][1]
        if prev == 'D':
            if curr == 'D':
                aDD += 1
            else:
                aDC += 1
        else:
            if curr == 'D':
                aCD += 1
            else:
                aCC += 1

    s_d = aDD + aDC
    s_c = aCD + aCC

    retaliatory = False
    independent = False
    if s_d >= 4 and s_c >= 2:
        p_dd = aDD / s_d
        p_cd = aCD / s_c
        if p_dd > p_cd + 0.30 and aDD >= 2:
            retaliatory = True
        elif p_dd <= p_cd + 0.10 and rec_rate > 0.35 and d_streak <= 2:
            independent = True

    if not retaliatory and s_d >= 3 and aDC >= 2 and aDD == 0 and rec_rate > 0.40 and d_streak == 0:
        independent = True

    hostile = False
    if opp_rate < 0.25 or rec_rate < 0.20:
        hostile = True
    if d_streak >= 5 and rec_rate <= 0.50 and aDD >= 1:
        hostile = True

    if hostile:
        return 'D'
    if independent and not retaliatory:
        return 'D'

    if opp_last == 'D':
        if d_streak <= 1 and opp_rate > 0.45 and rec_rate > 0.45 and not (s_c >= 5 and aCD >= 4):
            return 'C'
        if not retaliatory and d_streak <= 3 and my_d_streak < 2:
            return 'D'
        if (d_streak <= 5 or my_d_streak >= 2) and opp_rate > 0.40 and rec_rate > 0.30:
            return 'C'
        return 'D'

    if c_streak >= 6 and aDC >= 1 and aDD == 0 and not retaliatory and opp_rate > 0.50:
        return 'D'

    if c_streak >= 15 and n >= 25 and s_d < 8:
        if not retaliatory and (aDD < 2 or aDC > 0):
            if rng.random() < 0.05:
                return 'D'

    if n >= 95 and opp_rate > 0.70 and rec_rate > 0.60 and not retaliatory and aDD == 0 and aDC > 0:
        return 'D'

    return 'C'
